args.new_string:
import { unstable_noStore as noStore } from 'next/cache';

export default function Home() {
  // Opt out of static prerendering to ensure dynamic rendering on each request
  noStore();

  const timestamp = new Date().toISOString();
  const formattedTimestamp = new Date().toLocaleString('en-US', {
    dateStyle: 'full',
    timeStyle: 'long'
  });

  return (
    <main>
      <h1>Server Timestamp</h1>
      <p>This timestamp is generated on the server for each request:</p>
      <div style={{
        padding: '20px',
        backgroundColor: '#f0f0f0',
        borderRadius: '8px',
        margin: '20px 0',
        fontFamily: 'monospace'
      }}>
        <strong>ISO Format:</strong> {timestamp}
        <br />
        <strong>Formatted:</strong> {formattedTimestamp}
      </div>
      <p style={{ fontSize: '14px', color: '#666' }}>
        Reload the page to see the timestamp update with each request.
      </p>
    </main>
  );
}

